INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61989433', 61989433, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Pengadaan Tenaga Ahli Diseminasi #1', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 130075000, 'December 2025', 'APBD', 1, 1, '1 Orang x 11 Bulan', '1) Mempelajari isu-isu strategis serta visi dan misi Pemerintah Provinsi DKI Jakarta; 2) Menetapkan materi publikasi statistik sektoral; 3) Melaksanakan koordinasi internal/eksternal; 4) Menyusun jadwal publikasi statistik sektoral; 5) Memenuhi permintaan desain dan publikasi pada portal pemerintah Provinsi DKI Jakarta; 6) Memenuhi permintaan desain publikasi (Infografis/buku/leaflet/video dan lain-lain) sesuai dengan kebutuhan; 7) Mengevaluasi metode/prosedur publikasi statistik sektoral; 8) Menyelaraskan desain produk dengan brand design yang sudah disepakati.; 9) Melakukan riset dan penelitian terhadap pengalaman dan kebutuhan pengguna; 10) Menyediakan dan bertanggung jawab atas rencana inovasi, campaign, dan menciptakan produk-produk yang diinginkan dan sejalan dengan visi dan misi Pemerintah Provinsi DKI Jakarta; 11) Melakukan evaluasi produk-produk Bidang Data dan Statistik secara berkala; 12) Melakukan evaluasi design website (UI dan UX) secara berkala; 13) Mengoptimasi dan mengevaluasi SEO untuk memastikan konten mudah ditemukan oleh audiens secara online; 14) Berkolaborasi dengan tim lain untuk membuat campaign atau konten yang dapat menunjang kebutuhan Bidang Data dan Statistik; 15) Berkolaborasi dengan tim lain untuk mengevaluasi campaign atau konten yang dapat menunjang kebutuhan Bidang Data dan Statistik; 16) Melaksanakan tugas lainnya yang diperintahkan oleh Kepala Bidang Data dan Statistik dan/atau Ketua Subkelompok Statistik dan Analisis Kebijakan; dan 17) Membuat laporan pelaksanaan pekerjaan dalam bentuk tulisan/paper dan/atau presentasi serta softcopy.', '• Pendidikan minimal S1 Jurusan Pendidikan Bahasa Inggris /Ilmu Komunikasi / Desain Komunikasi Visual /Teknik Informatika /Teknik Elektronika • Memiliki pengalaman minimal 3 tahun • Memiliki sertifikasi kompetensi terkait “Data Management Staff / Desain Grafis ” yang dikeluarkan oleh BNSP, atau Instansi yang berwenang berdasarkan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 140517);
