INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61988865', 61988865, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Kemantren Kraton', 'Belanja Jasa Tenaga Administrasi -  Tenaga Administrasi Pemerintahan Lainnya (2) - Pemberdayaan Masyarakat di Kelurahan - Kelurahan Kadipaten', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 36672000, 'January 2026', 'APBD', 1, 1, '1', 'Ruang lingkup pekerjaan meliputi : 1) Mencatat, menyeleksi dan mengarahkan surat/naskah; 2) Mengendalikan surat dan memantau tindak lanjut surat; 3) Melakukan entry data arsip umum dan kepegawaian ke dalam komputer; 4) Membantu PPTK menyiapkan SPJ keuangan kegiatan 5) Menerima dan memeriksa berkas persyaratan yang diajukan warga, mengoreksi dan meregistrasi berkas serta memproses; 6) Mengolah dan memperbaharui perkembangan data dan informasi penyelenggaraan PATEN; 7) Mengarsipkan berkas permohonan dan persyaratan dari warga; 8) Membantu penyelesaian administrasi kegiatan Kelurahan; 9) Membantu pengadministrasian di bidang Keuangan dan Kepegawaian; 10) Membantu input data ke dalam Sistem Informasi yang berkaitan dengan perencanaan dan pelaporan keuangan; 11) Mengarsipkan berkas-berkas keuangan dan kepegawaian; 12) Melaksanakan tugas yang diperintahkan oleh atasan; 13) Melaporkan hasil pekerjaan kepada atasan. Lokasi pekerjaan di Kantor Kelurahan Kadipaten, Kemantren Kraton, Kota Yogyakarta. Fasilitas yang dapat disediakan oleh PA/PPKom adalah 1 (satu) unit Komputer', 'Tenaga terampil yang dibutuhkan meliputi : a. Tingkat pendidikan minimal SLTA atau sederajat b. Pengalaman dalam menangani pekerjaan yang sejenis/ sesuai bidang yang dibutuhkan c. Jumlah tenaga terampil yang dibutuhkan 1 (satu) orang d. Waktu penugasan sesuai ketentuan e. Tidak akan menuntut untuk diangkat menjadi PNS setelah bekerja sebagai Jasa Lainnya Orang Perseorangan dengan menyampaikan Surat Pernyataan', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 142143);
