INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61988886', 61988886, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'DINAS KOMUNIKASI, INFORMATIKA DAN STATISTIK', 'Pengadaan Tenaga Ahli Analisis #5', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 130075000, 'December 2025', 'APBD', 1, 1, '1 Orang x 11 Bulan', '1) Menyusun atau menyempurnakan metode/ prosedur analisis data dan publikasi data; 2) Melaksanakan pengolahan data dan analisa data; 3) Menyajikan hasil kajian dalam bentuk tulisan/paper dan/atau presentasi serta softcopy; 4) Menyusun publikasi terhadap data statistik dan hasil analisis data; 5) Memberi saran berdasarkan hasil temuan analisis yang telah diuji dengan tujuan untuk membantu meningkatkan pelayanan; 6) Melaksanakan dukungan pengolahan dan analisis data hasil pelaksanaan survei sesuai dengan kebutuhan; 7) Melakukan eksperimen model untuk mengolah data; 8) Memberikan transfer pengetahuan mengenai pengolahan dan analisis data; 9) Melakukan penelitian terkait data yang akan digunakan sebagai metode penentuan keputusan; 10) Membuat tabel pivot menggunakan software statistik; 11) Memvisualisasikan data dalam bentuk grafik; 12) Melakukan analisis data dalam jumlah yang besar/big data; 13) Mengidentifikasi masalah penganalisisan data; 14) Melaksanakan tugas lainnya yang diperintahkan oleh Kepala Bidang Data dan Statistik dan/atau Ketua Subkelompok Statistik dan Analisis Kebijakan; dan 15) Membuat laporan pelaksanaan pekerjaan dalam bentuk tulisan/paper dan/atau presentasi serta softcopy.', '• Pendidikan minimal S1 Jurusan Antropologi /Antropologi Sosial /Sastra Indonesia /Ekonomi Pembangunan /Administrasi Publik /Ilmu Administrasi Publik /Pemanfaatan Sumber Daya Perikanan /Psikologi /Informatika /Fisika /Teknik Elektro /Matematika/Statistika • Memiliki pengalaman minimal 3 tahun • Memiliki sertifikasi kompetensi terkait “Data Management Staff / Ilmuwan Data (Data Scientist) ” yang dikeluarkan oleh BNSP, atau Instansi yang berwenang berdasarkan perundang-undangan yang berlaku.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 142394);
