INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61992342', 61992342, 'analyze_legacy', 'Kementerian Imigrasi dan Pemasyarakatan', 'central', 'INSPEKTORAT JENDERAL', 'Pengadaan Sewa Kendaraan Dinas Fungsional Protokoler, Pejabat Eselon I, Operasional dan Kendaraan Fungsional Jemputan Pegawai Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyrakatan Tahun Anggaran 2026', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 2542800000, 'July 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1.0 PAKET', 'Pengadaan Sewa Kendaraan Dinas Fungsional Protokoler, Pejabat Eselon I, Operasional dan Kendaraan Fungsional Jemputan Pegawai Pada Inspektorat Jenderal Kementerian Imigrasi dan Pemasyrakatan Tahun Anggaran 2026. Pekerjaan ini meliputi penyediaan dan layanan sewa kendaraan dinas fungsional protokoler sebanyak 4 (empat) unit, kendaraan dinas bagi Pejabat Eselon I sebanyak 1 (satu) unit, kendaraan dinas operasional sebanyak 5 (lima) unit, serta kendaraan fungsional jemputan pegawai sebanyak 3 (tiga) unit untuk jangka waktu 12 (dua belas) bulan, termasuk pemeliharaan, perawatan, perbaikan, dan penggantian suku cadang selama masa kontrak, penyediaan asuransi kendaraan', 'Kendaraan dinas fungsional protokoler, kendaraan dinas bagi Pejabat Eselon I, dan kendaraan dinas operasional merupakan kendaraan roda empat berbasis listrik atau setara sesuai ketentuan peraturan perundang-undangan, dalam kondisi baru atau layak dan memenuhi standar teknis operasi dan memenuhi standar keselamatan berkendara, dengan kapasitas minimal lima penumpang serta dilengkapi fitur keselamatan dan kenyamanan standar. Kendaraan fungsional jemputan pegawai dapat menggunakan kendaraan non-listrik yang layak dan memenuhi standar teknis operasi sesuai ketentuan peraturan perundang-undangan. Seluruh kendaraan harus memiliki kelengkapan administrasi yang sah dan berlaku selama masa kontrak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 142412);
