INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61996451', 61996451, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'PUSAT DATA DAN INFORMASI KELUARGA', 'Penyediaan Tenaga Ahli IT Team Lead Rancangan Pengembangan Sistem Informasi  Pelaksanaan Pendataan Keluarga Satu Pintu', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 80300000, 'April 2026', 'APBD', 1, 1, '1 orang x 4 bulan', 'Melakukan review pada sistem backend dan frontend Membangun dan merancang sistem backend dan frontend dari suatu aplikasi Mendukung siklus pengembangan (konsep,desain, pengujian, rilis,operasional) Mengatasi berbagai bugs dan errors yang terjadi pada aplikasi dari sisi backend Berupaya untuk terus berinovasi dalam hal meningkatkan kualitas dan performa dari sistem aplikasi Melakukan Unit Test,Integration Test, serta mendampingi User Acceptance, Test setelah modul-modul dalam aplikasi dapat digunakan Melakukan debugging dan fixing terhadap program-program yang masih perlu diperbaiki Membuat script pemrograman yang terstruktur sehingga mempermudahdandimengerti oleh programmer lain jika ke depannya akan dikembangkan Memberikan pelatihan terhadap user dan transfer knowledge Berkolaborasi dengan frontend dan mobile dalam pengembangan aplikasi Melakukan perancangan struktur umum terkait sistem yang sesuai dengan identifikasi kebutuhan Melakukan perancangan solusi terkait permasalahan dan kebutuhan berdasarkan sistem informasi Memastikan kualitas dan keamanan sistem informasi yang dikembangkann menyusun konsep arsiktektur Sistem Informasi, dan mengendalikan implementasi Programing Memastikan sistem informasi terlindungi dari ancaman siber melalui kebijakan dari prosedur keamanan', 'Pendidikan terakhir S1 jurusan Ilmu Komputer/Sistem Informasi/Teknik Informatika Memiliki pengalaman kerja sebagai programmer minimal 14 tahun Memiliki kemampuan bahasa pemograman Java, Swagger, Angular (Mengerti Java Spring Boot lebih diutamakan) Memiliki konsep OOP dan/atau functional programming Memiliki kemampuan bahasa pemograman NodeJS dan PHP, Golang, Bootstrap menjadi nilai tambah Memahami konsep, implementasi dan maintenance relational dan non relational database (Postgres Lebih diutamakan) Memiliki kemampuan yang mendalam tentang sistem teknologi informasi (jaringan,basis data, aplikasi) Memahami konsep Container, REST API, Git Continous Integration dan Deployment menjadi nilai tambah. Diutamakan pernah mengikuti pelatihan ISO 27001 atau auditor keamanan sistem informasi', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 146116);
