INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62825590', 62825590, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Pekerjaan Umum, Perumahan dan Kawasan Permukiman', 'Pendataan Bangunan Gedung Kota Yogyakarta Tahap III', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 100000000, 'January 2026', 'APBD', 1, 1, '1 Dokumen', 'Dalam upaya mewujudkan layanan yang lebih cepat, efisien dan berkualitas serta menghindari potensi keterlambatan dan kerugian yang mungkin timbul, keberadaan data dan informasi yang valid menjadi kebutuhan mendasar. Aspek pendataan yang menyeluruh tentang jumlah bangunan, fungsi, status perizinan hingga riwayat perubahan bangunan Gedung menjadi komponen vital dalam sistem pelayanan yang terintegrasi. Konsekuensinya setiap daerah memiliki kewajiban untuk melaksanakan pendataan bangunan Gedung secara komprehensif dan melakukan pemutakhiran data secara berkala melalui mekanisme yang terstruktur dan dapat dipertanggungjawabkan. Untuk mengoptimalkan pengelolaan data bangunan Gedung di Kota Yogyakarta, dikembangkan sistem database spasial yang terintegrasi dan terstruktur dengan baik, dilengkapi dengan visualisasi peta interaktif yang memuat informasi posisi dan dimensi bangunan serta atribut data pendukung yang relevan.', '1) Melakukan digitasi bangunan gedung di Kota Yogyakarta 2) Menyiapkan template atribut non spasial 3) Menyusun webGIS berisi basis data bangunan gedung', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 146136);
