INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61998889', 61998889, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Komunikasi, Informatika dan Persandian', 'Jasa Perseorangan Aktivitas Pemrograman Komputer Lainnya 5', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 84000000, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Ruang lingkup pekerjaan: ●Konsentrasi pada Desain Sistem Informasi. ●Menerjemahkan dokumen BRD/SRS menjadi rancangan/desain sistem informasi. ●Melakukan pemeliharaan aplikasi eksisting, pembangunan, dan pengembangan aplikasi Jogja Smart Service (JSS) dan aplikasi yang masuk dalam Roadmap Smart City dan Master Plan e-Gov, serta aplikasi lainnya berdasarkan usulan dari OPD ●Menambah, mengembangkan atau menyesuaikan database eksisting ke dalam struktur dan platform baru sesuai kebutuhan. ●Melakukan uji coba aplikasi sampai dapat dioperasikan dengan baik. ●Memberikan laporan kemajuan pekerjaan, serta melaksanakan presentasi hasil kemajuan pekerjaan sesuai jadwal yang ditentukan. ●Membuat perbaikan aplikasi untuk menyesuaikan dengan kebutuhan pengguna. ●Membuat service setiap aplikasi yang dibangun agar dapat berinteraksi atau diintegrasikan dengan aplikasi lainnya. ●Memberikan pelatihan (TOT) penggunaan aplikasi kepada tim implementator. ●Membuat Dokumen Teknis Aplikasi yang dibangun.', 'Minimal S1 jurusan Teknik Informatika, Ilmu Komputer, Sistem Informasi, atau bidang lain yang relevan ●Minimal menguasai : a.Bahasa Pemrograman : PHP, Javascript, VB b.Framework : Laravel, React JS, Bootstrap, Tailwind c.Database : MySql, Mongodb d.Desain : Adobe XD, Photoshop, Illustrator, Figma, Draw.Io e.Lainnya : Premiere Pro, After Effect, Git, Lottie ●Mampu bekerja dalam team atau bekerja sendiri Berpengalaman membuat aplikasi web / mobile', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 146976);
