INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61999788', 61999788, 'analyze_legacy', 'Kota Yogyakarta', 'kabkota', 'Dinas Komunikasi, Informatika dan Persandian', 'Jasa Perseorangan Aktivitas Pemrograman Komputer Lainnya 17', 'Jasa Lainnya', 'Pengadaan Langsung', 'DI Yogyakarta, Yogyakarta (Kota)', 84000000, 'December 2025', 'APBD', 1, 1, '12 bulan', 'Ruang lingkup pekerjaan: ●Konsentrasi pada Desain Sistem Informasi. ●Melakukan pemeliharaan aplikasi eksisting, pembangunan, dan pengembangan aplikasi Jogja Smart Service (JSS) dan aplikasi yang masuk dalam Roadmap Smart City dan Master Plan e-Gov, serta aplikasi lainnya berdasarkan usulan dari OPD ●Menambah, mengembangkan atau menyesuaikan database eksisting ke dalam struktur dan platform baru sesuai kebutuhan. ●Melakukan uji coba aplikasi sampai dapat dioperasikan dengan baik. ●Memberikan laporan kemajuan pekerjaan, serta melaksanakan presentasi hasil kemajuan pekerjaan sesuai jadwal yang ditentukan. ●Membuat perbaikan aplikasi untuk menyesuaikan dengan kebutuhan pengguna. ●Membuat service setiap aplikasi yang dibangun agar dapat berinteraksi atau diintegrasikan dengan aplikasi lainnya. ●Memberikan pelatihan (TOT) penggunaan aplikasi kepada tim implementator. ●Membuat Dokumen Teknis Aplikasi yang dibangun.', 'Minimal S1 jurusan Teknik Informatika, Ilmu Komputer, Sistem Informasi, atau bidang lain yang relevan ●Minimal menguasai : a.Bahasa Pemrograman : PHP, Javascript, VB b.Framework : Laravel, React JS, Bootstrap, Tailwind c.Database : MySql, Mongodb d.Desain : Adobe XD, Photoshop, Illustrator, Figma, Draw.Io e.Lainnya : Premiere Pro, After Effect, Git, Lottie ●Mampu bekerja dalam team atau bekerja sendiri Berpengalaman membuat aplikasi web / mobile', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148423);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61995341', 61995341, 'analyze_legacy', 'Kota Mojokerto', 'kabkota', 'UPT PUSKESMAS KEDUNDUNG', 'Belanja Perangko, Materai Dan Benda Pos Lainnya (PL Barjas BLUD)', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Mojokerto (Kota)', 2000000, 'January 2026', 'BLUD', 1, 1, '1 tahun', 'Belanja Perangko, Materai Dan Benda Pos Lainnya', 'Belanja Materai - Materai 10.000', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148424);
INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62000030', 62000030, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Pengelolaan Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Penunjukan Langsung', 'DKI Jakarta, Jakarta Selatan (Kota)', 960000000, 'November 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '11 Bulan', 'Konsultan Pengelolaan Satuan Kerja ICCTF ini secara umum memiliki tugas sebagai kepala Sekretariat ICCTF yang akan mengelola operasional harian Sekretariat ICCTF termasuk mengawasi kinerja unit operasional dan program, mengembangkan dan mengelola rencana kerja dan rencana anggaran tahunan Sekretariat ICCTF untuk mendapat persetujuan MWA serta mengelola sekretariat dalam pelaksanaan proyek yang berjalan untuk menjamin pelaksanaan proyek di Satker ICCTF, serta memastikan proyek–proyek tersebut berjalan baik secara substansi maupun pelaporan keuangan. Konsultan ini bertanggung jawab dan melaporkan kegiatannya kepada ketua MWA melalui Sekretaris MWA. Sedangkan ruang lingkup pekerjaan Konsultan meliputi: 1. Aspek Perencanaan 2. Aspek Pelaksanaan Program/Kegiatan, Monitoring dan Evaluasi 3. Aspek Organisasi dan Tata Laksana 4. Aspek Keuangan dan Audit 5. Aspek Penguatan Aset 6. Aspek Penggalangan Dana', 'Adapun keluaran kegiatan dari Tenaga Konsultan ini adalah berupa dokumen kegiatan yang meliputi aspek: 1. Perencanaan a. Annual Work Plan (AWP) b. Procurement Plan c. Disbursement Plan d. Laporan pelaksanaan pengadaan barang/jasa dan pelaksanaan kontrak 2. Aspek Pelaksanaan Program/ Kegiatan dan Monitoring dan Evaluasi a. Laporan pelaksanaan program/kegiatan setiap Bulan untuk dilaporkan ke Koordinator Pokja b. Laporan pelaksanaan program/kegiatan setiap Triwulan untuk dilaporkan ke Ketua MWA c. Laporan Pemantauan/monitoring Pelaksanaan Program/kegiatan d. Hasil review terhadap Laporan pelaksanaan kegiatan yang disusun oleh Team Leader/ Program Manager e. Laporan Evaluasi Pelaksanaan Program/kegiatan f. Laporan perkembangan penyerapan anggaran, kegiatan pengadaan, capaian kegiatan dan hal-lainnya yang dianggap perlu setiap bulan kepada Ketua MWA dengan tembusan kepada PPK. 3. Aspek Organisasi dan Tata Laksana a. Konsep SOP untuk mendapatkan persetujuan Ketua MWA b. Konsep struktur organisasi Sekretariat untuk mendapatkan persetujuan Ketua MWA 4. Aspek Pelaksanaan Program/ Kegiatan dan Monitoring dan Evaluasi a. Laporan pelaksanaan program/kegiatan setiap Bulan untuk dilaporkan ke Koordinator Pokja b. Laporan pelaksanaan program/kegiatan setiap Triwulan untuk dilaporkan ke Ketua MWA c. Laporan Pemantauan/monitoring Pelaksanaan Program/kegiatan d. Hasil review terhadap Laporan pelaksanaan kegiatan yang disusun oleh Team Leader/ Program Manager e. Laporan Evaluasi Pelaksanaan Program/kegiatan f. Laporan perkembangan penyerapan anggaran, kegiatan pengadaan, capaian kegiatan dan hal-lainnya yang dianggap perlu setiap bulan kepada Ketua MWA dengan tembusan kepada PPK. 5. Aspek Keuangan dan Audit a. Dokumen Strategi progres penyerapan dana yang bersumber dari hibah dan Rupiah Murni per Triwulan b. Laporan status keuangan yang berasal dari hibah dan Rupiah Murni setiap bulannya c. Laporan pelaksanaan pencarian sumber-sumber pendanaan setiap Triwulan d. Laporan Audit Hibah e. Konsep tanggapan sebagai tindaklanjut rekomendasi auditor jika ada 6. Aspek Penguatan Aset Laporan status penggunaan aset kepada Ketua MWA selaku Kuasa Pengguna Barang ICCTF 7. Aspek Penggalangan Dana dan Penjangkaun Publik a. Laporan hasil negosiasi rencana pengembangan strategic melalui pencarian donor baru b. Publikasi profil Satker ICCTF melalui pemberitaan dalam dan luar negeri c. News Letter Satker ICCTF d. Laporan upaya pencarian donor baru – dilaporkan kepada Ketua MWA', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148425);
