INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62825977', 62825977, 'analyze_legacy', 'Provinsi DKI Jakarta', 'provinsi', 'LABORATORIUM LINGKUNGAN HIDUP DAERAH', 'Penyediaan Sewa Mesin Fotokopi', 'Jasa Lainnya', 'E-Purchasing', 'DKI Jakarta, Jakarta Selatan (Kota)', 62759424, 'January 2026', 'APBD', 1, 0, '1 paket', 'menyediakan satu unit mesin fotocopy dan perawatannya dalam bentuk sewa sehingga terpenuhi kebutuhan penggandaan dokumen-dokumen maupun formulir-formulir kerja laboratorium.', 'Ruang lingkup kegiatan Penyediaan Sewa Mesin Fotocopy secara umum meliputi: Menyediakan Sewa mesin fotocopy sebanyak 1 (satu) unit di Laboratorium Lingkungan Hidup Daerah; Melakukan pemasangan dan instalasi mesin Fotocopy di tempat yang ditentukan maksimal 1 (satu) hari kalender setelah penandatangan kontrak/surat pesanan; Pemeliharaan/perawatan secara berkala semua mesin fotocopy minimal dengan kunjungan ke lokasi pemasangan sebulan sekali; Penanganan atas kerusakan mesin fotocopy meliputi: Kecepatan pelayanan teknis tiba di lokasi dan kesanggupan melakukan pengecekan dalam waktu maksimal 4 jam sejak adanya laporan. Apabila gangguan/kerusakan tidak dapat diatasi dalam waktu tersebut maka penyedia harus sanggup memastikan fotocopy tersebut dapat berjalan normal atau dilakukan penggan tia dengan spesfikasi yang sama maksimal 2x24 ham sejak laporan gangguan/kerusakan. Menyediakan tinta untuk masing-masing mesin fotocopy selama pelaksanaan pekerjaan sewa mesin fotocopy; Menyampaikan laporan hasil pekerjaan atas pelayanan jasa sewa mesin fotocopy setiap sebulan sekali kepada PPK; Mencantumkan/menempelkan alamat kanal pengaduan yang dapat dihubungi setiap waktu (1x24 jam) pada unit mesin fotocopy; Mesin fotocopy harus sudah dalam kondisi baik dan siap pakai', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148596);
