INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('61999231', 61999231, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Sewa Ruang Kantor dan Jasa Pengelolaan Lippo Kuningan', 'Jasa Lainnya', 'Dikecualikan', 'DKI Jakarta, Jakarta Selatan (Kota)', 2775600288, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '12', 'Ruang lingkup pekerjaan sewa ruang kantor dan jasa pengeloaan adalah sebagai berikut: 1. Penyediaan ruang kantor yang memenuhi standar kebutuhan ruang kerja yaitu yang memenuhi kriteria sebagai berikut : a) Jarak dengan Kantor Kementerian PPN/Bappenas maksimal 5 km b) Memiliki ruang kantor dengan kebutuhan sebagai berikut, yaitu dengan luasan 632 M2 dengan perincian kebutuhan sebagaimana terlampir c) Memiliki infrastruktur mekanikal elektrikal plumbing seperti sistem listrik yang memadai, sistem ac, sistem air bersih dan air kotor.', 'Tahun Anggaran 2026, kegiatan pada Satker ICCTF semakin padat sehingga memerlukan tempat yang nyaman dan menjamin keberlangsungan kegiatan, untuk itu dirasa perlu untuk melanjutkan sewa ruang kantor dan jasa pengelolaan di unit D dan E Gedung Lippo Kuningan Lantai 15, dengan pertimbangan sebagai berikut: Ruang Kantor : 1. Lokasi Gedung Lippo sangat strategis dan memiliki jarak yang tidak terlalu jauh dari kantor Kementerian PPN/Bappenas yaitu hanya 3,3 KM, sehingga memudahkan koordinasi staf ICCTF dengan Kementerian PPN/Bappenas, Kementerian/Lembaga terkait dan mitra kerja, dan tidak memerlukan waktu tempuh terlalu lama dari Kementerian Perencanaan Pembangunan/ Bappenas, dengan demikian pelaksanaan kegiatan akan menjadi lebih efektif dan efisien. 2. Tidak perlu menganggarkan dana untuk perpindahan/mobilisasi staf ke Gedung lain; 3. Unit/ruangan yang ada di Gedung Lippo memiliki luasan 635,30 m2 sehingga sesuai dengan kebutuhan para pegawai di Sekretariat ICCTF; 4. keamanan di gedung lippo sangat dapat diandalkan, sehingga menjamin keamanan dalam pelaksanaan kegiatan yaitu memiliki sistem MEP yang diisntal dengan standar yang baik dan telah dikelola secara profesional; 5. Fasilitas area parkir tersedia cukup luas dan mampu menampung kapasitas 460 lot parkir serta toilet sebanyak 5 ruangan di setiap lantai. 6. Sistem keselamatan dan keamanan seperti alarm, sprinkler, fire extinguisher terinstal dengan baik, tangga darurat berfungsi dan layak untuk digunakan, tanda petunjuk keselamatan evakuasi dan titik kumpul dari dalam ruangan dapat dilihat dengan baik dan dapat dipahami para pengguna gedung. 7. Sistem perawatan dan jasa pelayanan gedung dkelola oleh pihak lain dan dikelola secara profesional. Jasa Pengelolaan: 1. Pemeliharaan/perawatan area bersama dilakukan oleh penyedia Jasa Pengelolaan secara berkala baik dari sistem MEP, Fire Alarm sampai dengan Genset. 2. Pemeliharaan kebersihan pada area bersama, koridor, toilet, dan perlengkapan kebersihan/hygiene serta material supplies dengan menyediakan 3 orang tenaga kebersihan di lantai ruangan dengan perlengkapan serta bahan yang memadai. 3. Jasa pengamanan gedung , memiliki sistem barier yang hanya pengguna yang memiliki akses dapat memasuki gedung, untuk tamu melewati detektor dan akan dimintakan KTP utuk diberikan akses naik kelantai yang akan dikunjungi. 4. Di ruangan tiap lantai terdapat 6 Unit AC sentral yang berfungsi dengan baik. Pengelola juga bersedia memperpanjang operasional pendingin sesuai kebutuhan 5. Air dan listrik selalu lancar karena tercover dengan sistem genset yang baik dan didukung dengan supply listrik dari PLN. 6. Pengelola merespon cepat jika ada kendala kelistrikan di ruangan yang digunakan. 7. Sewa Ruangan sudah termasuk biaya pajak bumi bangunan. 8. Telah memiliki Sertifikat Layak Fungsi dari gedung mulai dari Lift sampai kepada proteksi kebaran yang diperbaharui setiap tahunnya oleh pengelola manajemen gedung Keluaran dari kegiatan ini adalah tersedianya fasilitas ruang kantor dengan jasa pengelolaan yang memadai untuk menjamin keberlangsungan dan kelancaran pelaksanaan kegiatan pada Satuan Kerja MWA ICCTF tahun anggaran 2026.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148653);
