INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62000157', 62000157, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'MAJELIS WALI AMANAT  DANA PERWALIAN PERUBAHAN IKLIM INDONESIAICCTF KEMENTERIAN PPNBAPPENAS', 'Jasa Konsultansi Penguatan Sistem Fiduciary dan Manajemen Hibah Satuan Kerja MWA ICCTF', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 385000000, 'December 2025', 'APBN - RUPIAH MURNI (A)', 1, 1, '10 Bulan', 'Ruang lingkup pekerjaan Jasa Konsultan Penguatan Sistem Fiduciary Dan Manajemen Hibah Satuan Kerja MWA Dana Perwalian Perubahan Iklim Indonesia/ICCTF dirancang untuk memastikan pengelolaan fiduciary, keuangan, dan manajemen hibah ICCTF dilaksanakan secara akuntabel, terintegrasi, dan berkelanjutan, sejalan dengan kompleksitas portofolio pendanaan serta agenda transformasi ICCTF menuju Innovative Development Fund (ID-Fund). Pelaksanaan pekerjaan dilakukan dengan pendekatan berbasis keluaran (output-based contract), yang mencakup penguatan sistem fiduciary dan tata kelola keuangan, manajemen hibah dan kepatuhan donor, penguatan sistem operasional pendukung, pengelolaan portofolio pendanaan dan persiapan pendanaan baru, serta dukungan strategis terhadap transformasi kelembagaan ICCTF, di bawah koordinasi dan arahan Pimpinan ICCTF serta sesuai dengan ketentuan peraturan perundang-undangan dan standar mitra pembangunan internasional, sebagai berikut: Penguatan Sistem Fiduciary dan Tata Kelola Keuangan Mengkoordinasikan dan mengendalikan penerapan sistem fiduciary ICCTF yang mencakup perencanaan keuangan, penganggaran, pelaksanaan, pelaporan, dan pengendalian internal sesuai ketentuan APBN dan standar donor. Memastikan keselarasan antara Annual Work Plan (AWP), Rencana Anggaran Biaya (RAB), serta realisasi anggaran Satker ICCTF dan proyek hibah. Menyusun, menelaah, dan memutakhirkan kebijakan, pedoman, dan prosedur fiduciary ICCTF untuk menjamin akuntabilitas dan konsistensi pelaksanaan. Mengawal kesiapan Satker ICCTF dalam menghadapi audit internal dan eksternal, termasuk pemenuhan dokumen pendukung dan tindak lanjut temuan audit. Manajemen Hibah dan Kepatuhan Donor Mengkoordinasikan pengelolaan hibah eksisting dan persiapan hibah baru ICCTF secara menyeluruh, termasuk pengendalian keuangan, kepatuhan donor, dan manajemen risiko. Melakukan reviu dan verifikasi terhadap dokumen keuangan hibah, permintaan penarikan dana, serta laporan keuangan Mitra Pelaksana. Memastikan pelaksanaan hibah sesuai dengan perjanjian hibah (grant agreement), ketentuan donor, dan regulasi nasional yang berlaku. Mengidentifikasi potensi risiko fiduciary dan operasional proyek hibah serta merumuskan langkah mitigasi secara sistematis bersama Mitra Pelaksana. Penguatan Sistem Operasional Pendukung Fiduciary Mengawal efektivitas sistem operasional pendukung fungsi fiduciary, termasuk pengelolaan administrasi keuangan, arsip, aset, dan dokumentasi hibah. Memberikan masukan strategis terhadap penyempurnaan SOP operasional Satker ICCTF agar mendukung pengelolaan hibah yang efisien dan tertib. Mengkoordinasikan pelaporan kinerja operasional yang relevan dengan pengelolaan fiduciary dan hibah kepada Pimpinan ICCTF. Manajemen Portofolio Pendanaan dan Persiapan Pendanaan Baru Mendukung Pimpinan ICCTF dalam pengelolaan portofolio pendanaan ICCTF secara terpadu, termasuk analisis kesiapan fiduciary untuk pendanaan baru. Terlibat dalam proses financial management assessment, due diligence, serta penyusunan dokumen pendukung pendanaan baru sesuai persyaratan donor. Memberikan masukan terhadap penyusunan atau pemutakhiran SOP pendanaan baru sebagai bagian dari penguatan sistem ICCTF/ID-Fund. Dukungan Strategis Transformasi ICCTF menuju ID-Fund Mendukung penguatan sistem fiduciary dan manajemen hibah sebagai fondasi transformasi ICCTF menuju Innovative Development Fund (ID-Fund). Memastikan kesiapan tata kelola keuangan dan hibah yang kredibel, terintegrasi, dan berkelanjutan untuk mendukung mandat multi-donor dan blended finance. Melaksanakan tugas lain yang relevan dengan penguatan fiduciary dan manajemen hibah sesuai arahan Pimpinan ICCTF', 'Keluaran untuk tenaga Jasa Konsultan Penguatan Sistem Fiduciary Dan Manajemen Hibah Satuan Kerja MWA Dana Perwalian Perubahan Iklim Indonesia/ICCTF ini adalah sebagai berikut: 1. Manajemen Keuangan, Perencanaan dan Analisis a. Dokumen Revisi Annual Work Plan Satker ICCTF Tahun Anggaran berjalan b. Dokumen Rencana Anggaran Biaya Kegiatan Satker ICCTF Tahun Anggaran berjalan c. Laporan Presentasi Manajemen Keuangan Konsolidasi dari semua pendanaan d. Laporan Keuangan Satker ICCTF Triwulan, Semester dan Tahunan e. Laporan Pengadaan barang dan jasa Satker ICCTF f. Laporan Monitoring anggaran triwulan g. Laporan Keuangan Un-audited 2. Efektifitas Operasional a. Draft masukan terhadap bisnis plan ICCTF b. Dokumen update SOP Operasional Satker ICCTF c. Laporan Bulanan dari staf Operasional yang sudah direview dan disetujui d. Laporan status Asset ICCTF e. Laporan status kinerja staf ICCTF 3. Project and Grant Management a. Dokumen Annual Work Plan Proyek Hibah untuk mendapatkan persetujuan dari Donor b. Dokumen Annual Work Plan Mitra Pelaksana Proyek Hibah Tahun Anggaran berjalan yang sudah diverifikasi c. Dokumen Permintaan Termin pembayaran dari Mitra Pelaksana Proyek Hibah yang sudah diverifikasi d. Laporan Keuangan dari Mitra pelaksana Proyek Hibah secara Bulanan, Triwulan dan Tahunan yang sudah diverifikasi e. Interim Financial report Proyek Hibah f. Laporan Un-audited Proyek Hibah g. Laporan Monitoring Anggaran dan Kegiatan Proyek Hibah h. Laporan Posisi keuangan dan disbursemen hibah secara triwulan i. Laporan hasil Financial Spotcheck proyek Hibah j. Dokumen Berita Acara Serah Terima Aset Proyek Hibah k. Dokumen update SOP Pelaksanaan Proyek Hibah 4. Portfolio Management a. Dokumen draft masukan terhadap project Document pendanan baru khususnya pada perencanaan pendanaan b. Dokumen draft masukan terhadap Grant Agreement pendanaan baru c. Dokumen pengurusan administrasi pendaftaran hibah pendanaan baru dan pembukaan rekening d. Dokumen Financial Management Assessment pendanaan baru e. Dokumen draft masukan terhadap due diligence pendanaan baru f. Dokumen draft SOP Pendanaan baru sesuai yang dipersyaratkan donor g. Dokumen laporan sesuai yang diminta oleh Executive Director', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 148857);
