INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('62148591', 62148591, 'analyze_legacy', 'Kementerian Kesehatan', 'central', 'BALAI BESAR PELATIHAN KESEHATAN MAKASSAR', 'Pemeliharaan AC', 'Jasa Lainnya', 'Pengadaan Langsung', 'Sulawesi Selatan, Makassar (Kota)', 98532000, 'January 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '120 UNIT, 12 BULAN', 'Pemeliharaan AC kantor merupakan kegiatan untuk menjaga dan memastikan sistem pendingin udara berfungsi optimal, efisien, dan aman guna mendukung kenyamanan dan kelancaran operasional perkantoran.', '1. Pemeliharaan Rutin - Pembersihan filter udara, evaporator, dan grille AC - Pembersihan unit indoor dan outdoor dari debu, kotoran, atau jamur - Pemeriksaan kebocoran saluran pipa dan sambungan - Pemeriksaan kondisi kabel dan koneksi listrik 2. Pemeliharaan Berkala - Pemeriksaan dan pembersihan kondensor dan evaporator - Pemeriksaan tekanan dan suhu refrigeran - Pemeriksaan dan pelumasan motor kipas, bearing, dan komponen mekanikal - Pemeriksaan kinerja thermostat dan remote control 3. Perbaikan Ringan - Penggantian filter udara atau saringan udara yang rusak - Penggantian fan belt, bearing, atau komponen minor lainnya - Penambalan atau perbaikan kebocoran refrigeran sederhana - Perbaikan sistem kelistrikan minor 4. Pengisian dan Penyesuaian Refrigeran - Pengisian atau penggantian refrigeran sesuai spesifikasi pabrikan - Pengaturan tekanan refrigeran agar kinerja AC optimal 5. Standar Pelaksanaan - Pemeliharaan dilakukan oleh teknisi bersertifikat AC - Menggunakan suku cadang dan refrigeran sesuai standar pabrikan - Mematuhi SOP keselamatan kerja (K3) - Menjaga kebersihan dan keamanan area kerja selama pemeliharaan 6. Pelaporan - Setiap kegiatan pemeliharaan dicatat dalam log pemeliharaan AC - Laporan pemeliharaan disampaikan secara berkala kepada pengelola sarana prasarana', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 149622);
